-- Arbeitsrecht Berufsbildung > Rechte von Auszubildenden > Recht auf Unterweisung durch Ausbilder (§ 14 Abs. 1 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Hat ein Fachinformatiker Anspruch auf regelmäßige Unterweisung durch seinen Ausbilder?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG verpflichtet den Ausbilder dazu"}, {"text": "Nein", "correct": false, "because": "Unterweisung ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ausbildungsunternehmen die Unterweisung eines Fachinformatikers komplett an Kollegen delegieren?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG legt die Verantwortung beim Ausbilder fest"}, {"text": "Ja", "correct": false, "because": "Der Ausbilder bleibt primär verantwortlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbilder einem Fachinformatiker erklären, wie Programmieraufgaben zu lösen sind?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert fachgerechte Unterweisung"}, {"text": "Nein", "correct": false, "because": "Unterweisung umfasst relevante Inhalte"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker Unterweisung verlangen, wenn er eine Aufgabe nicht versteht?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG sichert dieses Recht"}, {"text": "Nein", "correct": false, "because": "Unterweisung ist ein Anspruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb die Unterweisung eines Fachinformatikers verweigern, wenn er bereits Grundkenntnisse hat?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG gilt unabhängig vom Vorwissen"}, {"text": "Ja", "correct": false, "because": "Unterweisung ist fortlaufend erforderlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage gibt einem Fachinformatiker das Recht auf Unterweisung durch den Ausbilder?', 2, '[{"text": "§ 14 Abs. 1 BBiG", "correct": true, "because": "Regelt die Unterweisungspflicht"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Ausbildungsqualität"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er keine ausreichende Unterweisung erhält?', 3, '[{"text": "Den Ausbilder und die IHK informieren", "correct": true, "because": "Das ist der rechtliche Weg gemäß § 14 Abs. 1 BBiG"}, {"text": "Selbstständig lernen", "correct": false, "because": "Nicht seine alleinige Pflicht"}, {"text": "Die Aufgabe ablehnen", "correct": false, "because": "Nicht die erste Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Unterweisung muss ein Ausbilder einem Fachinformatiker bieten?', 3, '[{"text": "Fachgerechte Anleitung zu IT-Aufgaben", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert Relevanz"}, {"text": "Nur allgemeine Betriebsregeln", "correct": false, "because": "Zu wenig spezifisch"}, {"text": "Keine praktische Anleitung", "correct": false, "because": "Praxis ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist primär verantwortlich für die Unterweisung eines Fachinformatikers?', 2, '[{"text": "Der Ausbilder", "correct": true, "because": "§ 14 Abs. 1 BBiG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule ergänzt nur"}, {"text": "Andere Kollegen", "correct": false, "because": "Ausbilder hat die Hauptverantwortung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Ausbilder einem Fachinformatiker keine Unterweisung gibt?', 3, '[{"text": "Die IHK kann den Betrieb verwarnen", "correct": true, "because": "Verstoß gegen § 14 Abs. 1 BBiG"}, {"text": "Der Auszubildende muss selbst lernen", "correct": false, "because": "Nicht seine Pflicht"}, {"text": "Die Ausbildung wird automatisch beendet", "correct": false, "because": "Nicht vorgesehen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte muss die Unterweisung eines Fachinformatikers laut § 14 Abs. 1 BBiG umfassen?', 4, '[{"text": "Programmiergrundlagen", "correct": true, "because": "Teil des Berufsbildes"}, {"text": "Netzwerkkonfiguration", "correct": true, "because": "Relevanter Ausbildungsinhalt"}, {"text": "Kaffeekochen für das Team", "correct": false, "because": "Keine fachliche Unterweisung"}, {"text": "Sicherheitsvorschriften im Betrieb", "correct": true, "because": "Notwendig für die Praxis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen kann ein Fachinformatiker ergreifen, wenn die Unterweisung fehlt?', 3, '[{"text": "Den Ausbilder darauf hinweisen", "correct": true, "because": "Erster Schritt zur Klärung"}, {"text": "Die IHK informieren", "correct": true, "because": "IHK überwacht die Einhaltung"}, {"text": "Selbstständig kündigen", "correct": false, "because": "Nicht primäre Lösung"}, {"text": "Aufgaben verweigern", "correct": false, "because": "Nicht empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Unterweisung eines Fachinformatikers gemäß § 14 Abs. 1 BBiG?', 4, '[{"text": "Anleitung zur Softwareentwicklung", "correct": true, "because": "Teil der fachlichen Ausbildung"}, {"text": "Erklärung von Betriebsabläufen", "correct": true, "because": "Notwendig für die Praxis"}, {"text": "Nur theoretische Vorträge", "correct": false, "because": "Praxis ist erforderlich"}, {"text": "Schulung in aktuellen Tools", "correct": true, "because": "Zeitgemäßigkeit ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der die Unterweisung eines Fachinformatikers vernachlässigt?', 3, '[{"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK überwacht § 14 Abs. 1 BBiG"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Bei Nachweis möglich"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Verlust der Ausbildungsberechtigung", "correct": true, "because": "Bei schweren Verstößen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben darf ein Ausbilder nicht als Unterweisung eines Fachinformatikers ausgeben?', 3, '[{"text": "Nur Anweisungen ohne Erklärung", "correct": true, "because": "Unterweisung erfordert Anleitung"}, {"text": "Schulung in Programmierung", "correct": false, "because": "Entspricht der Ausbildung"}, {"text": "Reine Beobachtung ohne Anleitung", "correct": true, "because": "Keine aktive Unterweisung"}, {"text": "Erklärung von Netzwerktechnik", "correct": false, "because": "Teil der Ausbildung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Unterweisung eines Fachinformatikers muss praktisch sein. b) Der Ausbilder darf die Unterweisung ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Praxis ist erforderlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) widerspricht § 14 Abs. 1 BBiG"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fachinformatiker hat Anspruch auf Unterweisung in aktuellen Technologien. b) Die Unterweisung kann an Dritte delegiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aktualität ist Pflicht, Delegation eingeschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nur teilweise richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Unterweisung muss dem Ausbildungsrahmenplan entsprechen. b) Ein Fachinformatiker muss selbst um Unterweisung bitten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rahmenplan ist bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Der Ausbilder muss einem Fachinformatiker komplexe Aufgaben erklären. b) Unterweisung ist nur in der Probezeit Pflicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Erklärung ist Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Unterweisung eines Fachinformatikers muss regelmäßig erfolgen. b) Der Betrieb kann die Unterweisung durch Videos ersetzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Regelmäßigkeit ist Pflicht, Videos allein reichen nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist unzureichend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

